36	// =========================================================================
37	//  Helpers shared by the kernels.
38	//
39	//  smem operand layout — the CUTLASS-canonical Major-K (INTERLEAVE/no-swizzle)
40	//  layout the ss-wgmma actually requires (NOT a plain row-major block). For an
41	//  operand of MN rows × K(=16) bf16, element (mn,k) lands at the bf16 index
42	//      idx(mn,k) = (k/8)*(MN*8) + mn*8 + (k%8)
43	//  i.e. K=16 is two stacked 8-wide core matrices, each an MN×8 row-major block.
44	//  Both A (MN=64) and B (MN=N) are staged this way; the wgmma then computes the
45	//  TN product  D[m,n] = sum_k A[m,k]·B[n,k]  with BOTH operands Major-K
46	//  (TransA=0, TransB=0 — Major::K==0 in cute). The python reference computes
47	//  exactly D = einsum("smk,snk->mn", A_bf16, B_bf16) over the SAME logical
48	//  [k_step,MN,16] tensors (global stays row-major; only the smem staging is
49	//  canonicalized). See make_desc_{A,B}_kmajor in wgmma.cuh.
50	// =========================================================================
51	
52	// Canonical Major-K bf16 smem index for element (mn,k) of an MN×16 tile.
53	__device__ __forceinline__ int kmajor_idx(int mn, int k, int MN) {
54	    return (k >> 3) * (MN * 8) + mn * 8 + (k & 7);
55	}
56	
57	template <int N>
58	__global__ void __launch_bounds__(128)
59	gemm_single_tile_kernel(
60	    const __nv_bfloat16* __restrict__ gA,   // [64*16] row-major M×K
61	    const __nv_bfloat16* __restrict__ gB,   // [N*16]  row-major N×K
62	    float* __restrict__ gD,                 // [64*N]  row-major M×N out
63	    int k_steps                              // number of 16-wide K tiles
64	) {
65	#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 900)
66	    // smem operand tiles: one A (64×16) + one B (N×16) per K-step, all staged.
67	    // For the single-tile / K-loop gates we stage ALL k_steps contiguously so
68	    // the descriptor generator just advances a pointer (no pipelining).
69	    extern __shared__ __nv_bfloat16 smem[];
70	    __nv_bfloat16* sA = smem;                       // [k_steps][64*16]
71	    __nv_bfloat16* sB = sA + (size_t)k_steps * 64 * 16; // [k_steps][N*16]
72	
73	    const int tid = threadIdx.x;  // 0..127 (one warpgroup)
74	
75	    // Cooperative load of all K-tiles into smem, SCATTERED from global
76	    // row-major ([k_step,MN,16]) into the canonical Major-K core-matrix layout
77	    // make_desc_*_kmajor requires. Each thread copies elements at its stride
78	    // and routes them via kmajor_idx. 64*16=1024 A elems + N*16 B elems / step.
79	    for (int k = 0; k < k_steps; ++k) {
80	        const __nv_bfloat16* aSrc = gA + (size_t)k * 64 * 16;   // row-major MxK
81	        const __nv_bfloat16* bSrc = gB + (size_t)k * N * 16;    // row-major NxK
82	        __nv_bfloat16* aDst = sA + (size_t)k * 64 * 16;
83	        __nv_bfloat16* bDst = sB + (size_t)k * N * 16;
84	        for (int i = tid; i < 64 * 16; i += 128) {
85	            int m = i >> 4, kk = i & 15;                 // global (m,k), K=16
86	            aDst[kmajor_idx(m, kk, 64)] = aSrc[i];
87	        }
88	        for (int i = tid; i < N * 16; i += 128) {
89	            int n = i / 16, kk = i % 16;
90	            bDst[kmajor_idx(n, kk, N)] = bSrc[i];
91	        }
92	    }
93	    __syncthreads();
94	
95	    wgs::WgmmaAccum<N> acc;  // fp32 fragment, N/2 regs/thread
96	
97	    // Descriptor generator: k-step k → {descA, descB} for the pre-staged tiles
98	    // (each tile already in canonical Major-K layout; the builder encodes the
99	    // canonical LBO=MN*16 / SBO=128 from the MN extent — see wgmma.cuh).
100	    auto gen = [&] (int k) {
101	        const __nv_bfloat16* aTile = sA + (size_t)k * 64 * 16;
102	        const __nv_bfloat16* bTile = sB + (size_t)k * N * 16;
103	        wgs::SmemDesc dA = wgs::make_desc_A_kmajor</*M=*/64, wgs::kSwizzleNone>(aTile);
104	        wgs::SmemDesc dB = wgs::make_desc_B_kmajor</*N=*/N,  wgs::kSwizzleNone>(bTile);
105	        return cuda::std::pair<wgs::SmemDesc, wgs::SmemDesc>(dA, dB);
106	    };
107	
108	    // The full choreography: fence → (k=0 overwrite, k>0 accumulate) →
109	    // commit → wait_group<0>. Both operands Major-K ⇒ TransA=0, TransB=0
110	    // (cute Major::K == 0); the wgmma reads D[m,n] = Σ_k A[m,k]·B[n,k].
111	    wgs::wgmma_mainloop_kchain<N, /*TransA=*/0, /*TransB=*/0>(acc, k_steps, gen);
112	
113	    // Epilogue: store each thread's N/2 fragment regs to the right (row,col)
114	    // of the M×N output using the authoritative fragment decode.
115	    #pragma unroll
116	    for (int i = 0; i < wgs::WgmmaAccum<N>::kRegs; ++i) {
117	        int row, col;
118	        wgs::wgmma_frag_decode(tid, i, N, row, col);
119	        gD[row * N + col] = acc.c[i];
120	    }
121	#else
122	    (void)gA; (void)gB; (void)gD; (void)k_steps;
123	#endif
124	}
