277	PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
278	    m.def("gemm_tile", &gemm_tile,
279	          "single-tile / K-loop ss-wgmma bf16 GEMM (m64xNx16), fp32 accum");
280	    m.def("gemm_tile_pipelined", &gemm_tile_pipelined,
281	          "pipelined (producer/consumer) ss-wgmma GEMM, same numerics");
282	    m.def("occupancy_for_smem", &occupancy_for_smem,
283	          "max active blocks/SM for a dynamic-smem request (0 = refuse)");
284	    m.def("probe_oversized_launch", &probe_oversized_launch,
285	          "attempt an oversized-smem launch; returns cuda error code (no hang)");
286	    m.def("device_max_dynamic_smem", &device_max_dynamic_smem,
287	          "device cudaDevAttrMaxSharedMemoryPerBlockOptin (bytes)");
288	}
